package com.jnapanam.sportszone.usermanagement.service;
import com.jnapanam.sportszone.common.exception.*;import com.jnapanam.sportszone.identity.model.*;import com.jnapanam.sportszone.identity.repository.*;import com.jnapanam.sportszone.usermanagement.dto.*;import com.jnapanam.sportszone.usermanagement.model.UserAdminNote;import com.jnapanam.sportszone.usermanagement.repository.UserAdminNoteRepository;import java.util.*;import org.springframework.data.domain.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class UserManagementService{private final UserRepository users;private final RoleRepository roles;private final RefreshTokenRepository refreshTokens;private final UserAdminNoteRepository notes;private final PasswordEncoder encoder;private final JdbcTemplate jdbc;public UserManagementService(UserRepository u,RoleRepository r,RefreshTokenRepository rt,UserAdminNoteRepository n,PasswordEncoder e,JdbcTemplate j){users=u;roles=r;refreshTokens=rt;notes=n;encoder=e;jdbc=j;}
 @Transactional(readOnly=true)public AdminUserPageResponse search(String q,UserStatus status,RoleName role,int page,int size){int safeSize=Math.max(1,Math.min(size,100));Page<User>p=users.search(clean(q),status,role,PageRequest.of(Math.max(0,page),safeSize,Sort.by("fullName").ascending()));return new AdminUserPageResponse(p.getContent().stream().map(AdminUserResponse::from).toList(),p.getNumber(),p.getSize(),p.getTotalElements(),p.getTotalPages());}
 @Transactional(readOnly=true)public AdminUserDetailResponse detail(UUID id){User u=user(id);return new AdminUserDetailResponse(AdminUserResponse.from(u),tags(id),notes.findByUserIdOrderByCreatedAtDesc(id).stream().map(UserNoteResponse::from).toList(),activity(id));}
 @Transactional public AdminUserResponse create(AdminCreateUserRequest r){String email=r.email().trim().toLowerCase(Locale.ROOT),mobile=mobile(r.mobile());if(users.existsByEmailIgnoreCase(email))throw new ConflictException("Email already exists");if(mobile!=null&&users.existsByMobile(mobile))throw new ConflictException("Mobile already exists");Role customer=role(RoleName.CUSTOMER);String hash=encoder.encode(r.temporaryPassword());User u=new User(r.fullName().trim(),email,mobile,hash,customer);u.password(hash,true);return AdminUserResponse.from(users.save(u));}
 @Transactional public AdminUserResponse update(UUID id,AdminUpdateUserRequest r){User u=user(id);String email=r.email().trim().toLowerCase(Locale.ROOT),mobile=mobile(r.mobile());users.findByEmailIgnoreCase(email).filter(x->!x.getId().equals(id)).ifPresent(x->{throw new ConflictException("Email already exists");});if(mobile!=null&&count("SELECT COUNT(*) FROM users WHERE mobile=? AND id<>?",mobile,id)>0)throw new ConflictException("Mobile already exists");u.update(r.fullName(),email,mobile,r.addressLine(),r.city(),r.state(),r.postalCode(),r.emergencyContactName(),r.emergencyContactMobile());return AdminUserResponse.from(u);}
 @Transactional public AdminUserResponse status(UUID id,UserStatusRequest r,boolean superAdmin){User u=user(id);if(privileged(u)&&!superAdmin)throw new org.springframework.security.access.AccessDeniedException("Only a super administrator can change a privileged account");u.status(r.status());if(r.status()!=UserStatus.ACTIVE)revoke(id);return AdminUserResponse.from(u);}
 @Transactional public AdminUserResponse roles(UUID id,UserRolesRequest r){User u=user(id);boolean removingSuper=u.getRoles().stream().anyMatch(x->x.getName()==RoleName.SUPER_ADMIN)&&!r.roles().contains(RoleName.SUPER_ADMIN);if(removingSuper&&users.countByRole(RoleName.SUPER_ADMIN)<=1)throw new ConflictException("The final super administrator cannot be removed");Set<Role>resolved=new LinkedHashSet<>();for(RoleName n:r.roles())resolved.add(role(n));u.replaceRoles(resolved);revoke(id);return AdminUserResponse.from(u);}
 @Transactional public void resetPassword(UUID id,AdminPasswordResetRequest r,boolean superAdmin){User u=user(id);if(privileged(u)&&!superAdmin)throw new org.springframework.security.access.AccessDeniedException("Only a super administrator can reset a privileged account");u.password(encoder.encode(r.temporaryPassword()),true);revoke(id);}
 @Transactional public void changePassword(UUID id,ChangePasswordRequest r){User u=user(id);if(!encoder.matches(r.currentPassword(),u.getPasswordHash()))throw new BadRequestException("Current password is incorrect");u.password(encoder.encode(r.newPassword()),false);revoke(id);}
 @Transactional public UserNoteResponse note(UUID targetId,UUID authorId,AdminNoteRequest r){return UserNoteResponse.from(notes.save(new UserAdminNote(user(targetId),user(authorId),r.note())));}
 @Transactional public Set<String>tags(UUID id,UserTagsRequest r){user(id);jdbc.update("DELETE FROM user_tags WHERE user_id=?",id);if(r.tags()!=null)for(String tag:r.tags())jdbc.update("INSERT INTO user_tags(user_id,tag) VALUES (?,?)",id,tag.trim().toUpperCase(Locale.ROOT));return tags(id);}
 @Transactional(readOnly=true)public List<String>roleNames(){return roles.findAll().stream().map(x->x.getName().name()).sorted().toList();}
 @Transactional public AdminUserResponse paymentPolicy(UUID id,PaymentPolicyRequest r){User u=user(id);u.paymentPolicy(r.requiresUpfrontPayment());return AdminUserResponse.from(u);}
 private CustomerActivitySummary activity(UUID id){return new CustomerActivitySummary(count("SELECT COUNT(*) FROM bookings WHERE user_id=?",id),count("SELECT COUNT(*) FROM bookings WHERE user_id=? AND checked_in_at IS NOT NULL",id),count("SELECT COUNT(*) FROM customer_memberships WHERE user_id=?",id),count("SELECT COUNT(*) FROM training_enrollments WHERE user_id=?",id),count("SELECT COUNT(*) FROM tournament_teams WHERE captain_user_id=?",id),count("SELECT COUNT(*) FROM payment_orders WHERE user_id=?",id),count("SELECT COALESCE(SUM(amount_paise),0) FROM payment_orders WHERE user_id=? AND status IN ('PAID','PARTIALLY_REFUNDED','REFUNDED')",id),count("SELECT COALESCE(SUM(pr.amount_paise),0) FROM payment_refunds pr JOIN payment_orders po ON po.id=pr.payment_order_id WHERE po.user_id=? AND pr.status='PROCESSED'",id));}
 private Set<String>tags(UUID id){return new LinkedHashSet<>(jdbc.queryForList("SELECT tag FROM user_tags WHERE user_id=? ORDER BY tag",String.class,id));}private long count(String sql,Object...args){Number n=jdbc.queryForObject(sql,Number.class,args);return n==null?0:n.longValue();}private void revoke(UUID id){refreshTokens.findByUserIdAndRevokedAtIsNull(id).forEach(RefreshToken::revoke);}private User user(UUID id){return users.findById(id).orElseThrow(()->new NotFoundException("User not found"));}private Role role(RoleName n){return roles.findByName(n).orElseThrow(()->new IllegalStateException("Role is missing: "+n));}private static String clean(String v){return v==null||v.isBlank()?"":v.trim();}private static String mobile(String v){return v==null||v.isBlank()?null:v.replaceAll("[ -]","");}private static boolean privileged(User u){return u.getRoles().stream().anyMatch(r->r.getName()==RoleName.ADMIN||r.getName()==RoleName.SUPER_ADMIN);}
}
